// A tiny model of JSX. h() is what JSX compiles to: it only builds plain objects.
function h(type, props, ...children) {
  return { type, props: { ...props, children } }
}

// render() walks the objects and produces HTML text, the way React produces DOM.
function render(node) {
  if (node === null || node === undefined || node === true || node === false) return ''
  if (typeof node === 'string' || typeof node === 'number') return String(node)
  if (Array.isArray(node)) return node.map(render).join('')
  if (typeof node.type === 'function') return render(node.type(node.props)) // a component
  const { children, ...attrs } = node.props
  const attrText = Object.entries(attrs)
    .map(([key, value]) => ` ${key === 'className' ? 'class' : key}="${value}"`)
    .join('')
  return `<${node.type}${attrText}>${render(children)}</${node.type}>`
}

function Badge(props) {
