function TodoList() {
  const [todos, setTodos] = useState([])

  function add(text) {
    setTodos([...todos, { id: Date.now(), text, done: false }])
  }
  function toggle(id) {
    setTodos(todos.map((t) => (t.id === id ? { ...t, done: !t.done } : t)))
  }

  return (
    <ul>
      {todos.map((t) => (
        <li key={t.id} onClick={() => toggle(t.id)}>{t.text}</li>
      ))}
      <button onClick={() => add('New task')}>Add</button>
    </ul>
  )
}

