// React compares old and new state with Object.is.
// The same reference means "nothing changed", so React skips the re-render.
function wouldRerender(oldState, newState) {
  return !Object.is(oldState, newState)
}

const todos = [{ id: 1, text: 'Learn JSX', done: false }]

