// The update logic of a controlled form, without the DOM.
// Each keystroke produces an event; the handler returns the next state.
function handleChange(form, event) {
  return { ...form, [event.target.name]: event.target.value }
}

// Derived values: computed from state on every render, never stored
function isValid(form) {
  return form.email.includes('@') && form.password.length >= 8
}

