// Two requests race. The first is slower, so its answer arrives last.
const delays = { 1: 300, 2: 100 }
const names = { 1: 'Ana', 2: 'Ben' }
function fetchUser(id) {
  console.log(`request for user ${id} started`)
  return new Promise((resolve) => setTimeout(() => resolve({ id, name: names[id] }), delays[id]))
}

let shown = 'Loading...' // what the page shows

// Works like a useEffect body that depends on [userId]
function loadUser(userId) {
  let ignore = false
  fetchUser(userId).then((user) => {
    // TODO: skip this update when the request is stale
    shown = user.name
  })
  return () => {
    ignore = true
  }
}

// Click user 1, then user 2 before the first response arrives
const cleanupFirst = loadUser(1)
cleanupFirst() // React runs the old cleanup when userId changes
loadUser(2)

setTimeout(() => console.log('final screen:', shown), 400)

