// A cart reducer: a pure function (state, action) => next state.
function cartReducer(cart, action) {
  switch (action.type) {
    case 'added': {
      const line = cart.find((l) => l.id === action.id)
      if (line) {
        return cart.map((l) => (l.id === action.id ? { ...l, qty: l.qty + 1 } : l))
      }
      return [...cart, { id: action.id, qty: 1 }]
    }
    case 'removed':
      return cart // TODO: return a new array without the line for action.id
    default:
      throw new Error(`Unknown action: ${action.type}`)
  }
}

const actions = [
  { type: 'added', id: 'apple' },
  { type: 'added', id: 'pear' },
  { type: 'added', id: 'apple' },
  { type: 'removed', id: 'pear' },
]

// useReducer applies each dispatched action in turn, like reduce does here
const cart = actions.reduce(cartReducer, [])
